function makeCounters() {
  // return an array of three functions
}

const counters = makeCounters();
counters.forEach((fn) => fn());

questions.answer:
function makeCounters() {
  const counters = [];
  for (let i = 0; i < 3; i++) {
    counters.push(() => console.log(i));
  }
  return counters;
}

const counters = makeCounters();
counters.forEach((fn) => fn());
// 0
// 1
// 2
